package org.transittr;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.graphics.drawable.*;import java.util.*;import org.json.*;
/** Standalone watch interface. Network refresh runs only while the board is visible. */
public final class WearActivity extends Activity {
 private static final int WHITE=0xfff3f7f4,MUTED=0xffa6b9b0,ACCENT=0xff90d5bb;private final Handler handler=new Handler();private final int[] ids=CityRegistry.ids();private LinearLayout body;private boolean foreground,board;private int generation;
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);return t;}private GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(14));return d;}private Button button(String s){Button b=new Button(this);b.setText(s);b.setTextSize(13);b.setTextColor(WHITE);b.setBackgroundDrawable(shape(0xff21312c));return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff000000);showBoard();}
 private void layout(){generation++;handler.removeCallbacksAndMessages(null);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(0xff000000);scroll.setFillViewport(false);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(24),dp(18),dp(24),dp(28));scroll.addView(body);setContentView(scroll);}
 private void showBoard(){board=true;layout();TextView title=text("TRANSIT TR",13,MUTED);title.setGravity(Gravity.CENTER);body.addView(title);TextView header=text("Varışlar",21,WHITE);header.setGravity(Gravity.CENTER);header.setPadding(0,dp(5),0,dp(10));body.addView(header);final ArrayList<WidgetFavorites.Entry> entries=WidgetFavorites.all(this);if(entries.isEmpty()){TextView empty=text("Durak ve hat ekle. Saat kayıtları telefondan ayrıdır.",14,MUTED);empty.setGravity(Gravity.CENTER);body.addView(empty);}final TextView[] states=new TextView[entries.size()];for(int i=0;i<entries.size();i++){final WidgetFavorites.Entry e=entries.get(i);LinearLayout row=new LinearLayout(this);row.setOrientation(1);row.setPadding(dp(12),dp(10),dp(12),dp(10));row.setBackgroundDrawable(shape(0xff18251f));TextView name=text(e.line+"  ·  "+WidgetFavorites.cityName(e.city),15,ACCENT);name.setTypeface(Typeface.DEFAULT,Typeface.BOLD);row.addView(name);row.addView(text("Durak "+e.stop,12,MUTED));states[i]=text("Yükleniyor…",20,WHITE);row.addView(states[i]);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);body.addView(row,lp);row.setOnLongClickListener(new View.OnLongClickListener(){public boolean onLongClick(View v){remove(e);return true;}});}Button add=button("Durak + hat ekle");body.addView(add,new LinearLayout.LayoutParams(-1,dp(48)));add.setOnClickListener(new View.OnClickListener(){public void onClick(View v){configure();}});if(foreground&&!entries.isEmpty())refresh(entries,states);}
 private void refresh(final ArrayList<WidgetFavorites.Entry> entries,final TextView[] states){final int token=++generation;new Thread(new Runnable(){public void run(){for(int i=0;i<entries.size();i++){if(!foreground||!board||token!=generation)return;final int index=i;String eta;try{JourneyData.Snapshot snap=WidgetArrivals.fetch(entries.get(i));JSONObject value=WidgetArrivals.select(snap,entries.get(i),System.currentTimeMillis());eta=value.optString("eta","—");}catch(Exception e){eta="Bağlantı yok";}final String result=eta;handler.post(new Runnable(){public void run(){if(foreground&&board&&token==generation)states[index].setText(result);}});}handler.postDelayed(new Runnable(){public void run(){if(foreground&&board&&token==generation)showBoard();}},60000);}}).start();}
 private void configure(){board=false;layout();TextView heading=text("Durak ekle",19,WHITE);heading.setGravity(Gravity.CENTER);body.addView(heading);final Spinner city=new Spinner(this);city.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,CityRegistry.names()));body.addView(city,new LinearLayout.LayoutParams(-1,dp(48)));final EditText stop=new EditText(this),line=new EditText(this);stop.setTextColor(WHITE);stop.setHintTextColor(MUTED);stop.setHint("Durak numarası");stop.setSingleLine(true);stop.setInputType(2);line.setTextColor(WHITE);line.setHintTextColor(MUTED);line.setHint("Hat kodu");line.setSingleLine(true);body.addView(stop,new LinearLayout.LayoutParams(-1,dp(50)));body.addView(line,new LinearLayout.LayoutParams(-1,dp(50)));Button save=button("Kaydet");body.addView(save,new LinearLayout.LayoutParams(-1,dp(48)));save.setOnClickListener(new View.OnClickListener(){public void onClick(View v){try{WidgetFavorites.add(WearActivity.this,ids[city.getSelectedItemPosition()],stop.getText().toString(),line.getText().toString(),"","");showBoard();}catch(Exception e){Toast.makeText(WearActivity.this,"Durak ve hat kodunu kontrol et",Toast.LENGTH_LONG).show();}}});}
 private void remove(final WidgetFavorites.Entry entry){new AlertDialog.Builder(this).setTitle("Kaydı kaldır?").setMessage(entry.line+" · "+entry.stop).setNegativeButton("Vazgeç",null).setPositiveButton("Kaldır",new android.content.DialogInterface.OnClickListener(){public void onClick(android.content.DialogInterface d,int w){WidgetFavorites.remove(WearActivity.this,entry.id);showBoard();}}).show();}
 @Override public void onBackPressed(){if(!board)showBoard();else super.onBackPressed();}@Override protected void onResume(){super.onResume();foreground=true;if(board)showBoard();}@Override protected void onPause(){foreground=false;generation++;handler.removeCallbacksAndMessages(null);super.onPause();}
}
